/**
 * Extends the knowledge base by loading additional items from a supplementary JSON file.
 * If the file is not found, is empty, or contains invalid data, the original knowledge base remains unchanged.
 * @param {string} jsonFilePath - The path to the supplementary JSON file.
 */
export async function extendKnowledgeBase(jsonFilePath: string): Promise<void> {
  try {
    const response = await fetch(jsonFilePath);

    // If the file is not found or there's another server error, do nothing.
    if (!response.ok) {
      console.warn(
        `Supplementary knowledge file not found or failed to load: ${jsonFilePath}`,
      );
      return;
    }

    const supplementaryData = (await response.json()) as KnowledgeItem[];

    // Check if the data is a non-empty array
    if (Array.isArray(supplementaryData) && supplementaryData.length > 0) {
      knowledgeBase.push(...supplementaryData);

      // Update the allKnownTerms array
      allKnownTerms = knowledgeBase.map((item) => item.term);

      console.log(
        `${supplementaryData.length} new items added to the knowledge base.`,
      );
    }
  } catch (error) {
    console.error(
      `Error processing supplementary knowledge file ${jsonFilePath}:`,
      error,
    );
    // If there's an error (e.g., network issue, invalid JSON), we do nothing to the knowledge base.
  }
}

/**
 * Tests all links in the knowledge base and generates a CSV report.
 * This function is designed to be run in an environment that supports the fetch API (like a modern browser or Node.js).
 * Note: When run in a browser, this may be affected by CORS (Cross-Origin Resource Sharing) policies.
 * A more reliable execution environment would be a server-side script (e.g., Node.js).
 *
 * @returns A promise that resolves to a string containing the CSV report.
 */
export async function testLinksAndGenerateReport(): Promise<string> {
  // CSV header
  let csvReport = "Termine,URL,Stato,Codice di Stato\n";

  for (const item of knowledgeBase) {
    if (item.links && item.links.length > 0) {
      for (const link of item.links) {
        if (!link.url) continue; // Skip if URL is empty

        let status = "Non Funzionante";
        let statusCode: number | string = "N/A";

        try {
          // Using a proxy to bypass CORS issues in the browser
          const proxyUrl = "https://api.allorigins.win/raw?url=";
          const response = await fetch(
            proxyUrl + encodeURIComponent(link.url),
            { method: "HEAD", mode: "cors" },
          );

          statusCode = response.status;
          if (response.ok) {
            status = "OK";
          } else {
            status = "Non Funzionante";
          }
        } catch (error) {
          console.error(`Error testing link ${link.url}:`, error);
          status = "Errore di Rete";
        }

        const csvRow = `"${item.term.replace(/"/g, '""')}","${link.url}","${status}",${statusCode}\n`;
        csvReport += csvRow;
      }
    }
  }

  return csvReport;
}
